const esc=(s='')=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function criterionSummary(result){
 const rows=result.criteria||[],met=rows.filter(c=>c.status==='met').length,unresolved=rows.filter(c=>c.status==='uncertain').length,work=rows.length-met-unresolved;
 if(!rows.length)return 'Task criteria · no judgement available';
 return 'Task criteria · '+[met?`${met} met`:'',work?`${work} need attention`:'',unresolved?`${unresolved} unresolved`:''].filter(Boolean).join(' · ');
}
export function coachingHistory(result){
 const history=result.coaching_history||[];if(!history.length)return '';
 return `<section class="coaching-history"><h3>This includes earlier tutor wording</h3><p>If the review questions that wording, compare the tutor’s suggestion with your original before revising again. A suggestion can introduce a problem; it does not become a requirement.</p><details><summary>Compare my original and the tutor suggestion</summary>${history.map(h=>`<article><small>Your earlier wording</small><blockquote>${esc(h.original)}</blockquote><small>The tutor’s proposed wording</small><blockquote>${esc(h.suggestion)}</blockquote><p class="tiny">Matched with minor case, spelling or punctuation differences. This identifies a text match; it does not establish how the wording entered your draft.</p></article>`).join('')}</details></section>`;
}
export function reviewProgress(job){
 const steps=[['context','Saved context'],['first_reading','First reading'],...(job.review_mode==='careful'&&job.kind!=='show_example'?[['second_reading','Second reading']]:[]),['compare','Compare & check']];
 const current=steps.findIndex(([key])=>key===job.stage?.stage),seen=new Set((job.stages||[]).map(s=>s.stage));
 const seconds=job.stage?Math.max(0,Math.round((Date.now()-Date.parse(job.stage.created))/1000)):0;
 return `<h3>${job.status==='queued'?'Waiting for the local tutor':esc(job.stage?.label||'Starting your review')}…</h3><ol class="review-steps" aria-label="Feedback stages">${steps.map(([key,label],i)=>`<li class="${i===current?'current':seen.has(key)?'done':''}" ${i===current?'aria-current="step"':''}>${seen.has(key)&&i!==current?'✓ ':''}${label}</li>`).join('')}</ol><p class="tiny" role="status">${seconds?`${seconds}s in this stage. `:''}Your answer is saved. ${job.review_mode==='careful'?'The first validated feedback appears below while the separate check continues.':'Quick mode uses one reading.'} Open <strong>Continue your work</strong> at the top of any page to return. Timing depends on the local model and passage.</p>`;
}
export function firstReadingPreview(job){
 const r=job.result;if(!r)return '';
 return `<section class="first-reading-preview" aria-label="First reading preview"><h3>First feedback is ready</h3><p class="tiny">${r.quality?.first_feedback_seconds??'?'} seconds to the first reading. The second reading is still checking it and may disagree. You can revise your text now; both readings assess the submitted version. Completion waits for the final review.</p><p>${esc(r.summary)}</p><h4>What already works</h4>${r.strengths.map(s=>`<p><q>${esc(s.quote)}</q> — ${esc(s.explanation)}</p>`).join('')||'<p>No specific strength was identified in this reading.</p>'}<h4>What to check</h4>${r.issues.map(i=>`<p><strong>${esc(i.category.replaceAll('_',' '))}:</strong> ${esc(i.explanation)} ${esc(i.hint||'')}</p>`).join('')||'<p>This reading proposed no correction. Keep the wording that works; the separate check is still running.</p>'}<details><summary>First reading against each criterion</summary><ul>${r.criteria.map(c=>`<li><strong>${esc(c.status)} — ${esc(c.criterion)}:</strong> ${esc(c.explanation)}</li>`).join('')}</ul></details></section>`;
}
export function readingReasons(c){return c.readings&&c.status==='uncertain'?`<details class="reading-reasons"><summary>Compare the reasons</summary>${c.readings.map(r=>`<p><strong>Reading ${r.reading} · ${esc(r.status)}:</strong> ${esc(r.explanation)}</p>`).join('')}</details>`:''}
export function qualityNotice(r){
 const q=r.quality;if(!q)return '';
 const titles={agreement:'Two readings agree on the criteria',disagreement:'The tutor readings disagree',provisional:'The second reading did not finish',single_reading:'One grounded reading',contract_check:'Check the response requirement',needs_review:'Check these feedback judgements together'};
 return `<section class="feedback-quality ${['disagreement','provisional','needs_review'].includes(q.status)?'needs-review':''}" aria-label="Review quality"><strong>${esc(titles[q.status]||'Review checks')}</strong><p>${q.auto_completion_allowed?'This review supports completion of this exercise.':q.status==='disagreement'?'This review is inconclusive. Keep your current text while comparing the reasons. Disagreement does not establish a writing error. Any completion already earned is kept; you can also record your own criteria review.':q.status==='provisional'?'Your first feedback is saved. A completed second reading is needed before this review can award completion.':'Use the criteria below to decide your next revision.'}</p>${(q.consistency_flags||[]).length?`<ul>${q.consistency_flags.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`:''}${q.verification_error?`<p>${esc(q.verification_error)}</p><button class="btn secondary" id="retry-verification">Retry the careful review</button>`:''}<p class="tiny">${q.same_model===true?'Both readings used the same local model in separate calls. ':''}Agreement can still be wrong; it does not verify scientific evidence.</p></section>`;
}
export function feedbackSources(r){
 const q=r.quality;if(!q)return '';
 return `<details class="feedback-trace"><summary>Writing guidance and review checks</summary><p>${q.transport==='mcp-stdio'?'The local MCP service supplied the saved task, writing guidance and mechanical checks.':esc(q.context_notice||'Saved context read on this Mac.')}</p>
 ${(q.guidance||[]).map(g=>`<div class="guidance-record"><strong>${esc(g.title)}</strong><p>${esc(g.principle)}</p><p class="tiny">${esc(g.check)}</p><div class="actions"><a href="${esc(g.reading.url)}" target="_blank" rel="noreferrer">${esc(g.reading.title)} · PDF pp. ${g.reading.page}–${g.reading.end_page}</a>${g.practice_key?`<a href="#practice/${encodeURIComponent(g.practice_key)}">Practise this skill →</a>`:''}</div></div>`).join('')}
 <p class="tiny">These are the lab’s teaching summaries informed by the supplied books. The books do not verify your paper’s claims.</p><details><summary>What each reading found</summary>${(q.readings||[]).map((x,i)=>`<article class="reading-record"><h4>Reading ${i+1} · ${esc(x.generation.model)}</h4><p><strong>Meaning:</strong> ${esc(x.review.intended_meaning)}</p><p>${esc(x.review.summary)}</p><ul>${x.review.criteria.map(c=>`<li><strong>${esc(c.status)} — ${esc(c.criterion)}:</strong> ${esc(c.explanation)}</li>`).join('')}</ul>${(x.review.idea_coverage||[]).length?`<p><strong>Idea coverage:</strong></p><ul>${x.review.idea_coverage.map(v=>`<li>${esc(v.status)} — ${esc(v.idea)}: ${esc(v.explanation)}</li>`).join('')}</ul>`:''}${(x.review.meaning_concerns||[]).length?`<p><strong>Meaning questions:</strong></p><ul>${x.review.meaning_concerns.map(v=>`<li>${esc(v)}</li>`).join('')}</ul>`:''}${x.review.issues.length?`<p><strong>Proposed changes:</strong></p><ul>${x.review.issues.map(v=>`<li>${esc(v.explanation)} ${esc(v.hint)}</li>`).join('')}</ul>`:''}<p class="tiny">${x.generation.duration_seconds??'?'} seconds · prompt ${esc(x.generation.prompt_version||'unknown')} · reasoning ${esc(String(x.generation.reasoning_mode??'runtime default'))}</p></article>`).join('')}</details>
 <p class="tiny">Review ${q.pipeline_version} · ${q.duration_seconds}s total · ${q.tool_calls?.length||0} MCP calls · saved context <code>${esc(q.snapshot_hash?.slice(0,12)||'')}</code>. Quotation locations and criterion coverage were checked. Private reasoning traces are neither stored nor displayed.</p></details>`;
}
export function apiError(detail,status){
 if(typeof detail==='string')return detail;
 if(Array.isArray(detail)){
  const names={attempt_id:'Saved answer',reflection:'Review note',message:'Your question',model:'Local model',verifier_model:'Second reading model'};
  const problems=detail.map(e=>{const field=(e.loc||[]).filter(k=>!['body','query','path'].includes(k)).join('.');return `${names[field]||field||'Request'}: ${e.msg||'check this field'}`});
  if(problems.length)return problems.join('; ')+` (HTTP ${status})`;
 }
 return `The request could not be saved (HTTP ${status}). Your text is still here; retry after reconnecting.`;
}
